package main

const macAlignmentCSS = `
:root{--primary:#303034;--on-primary:#fff;--accent:#eaeaee;--bg:#f7f7f8;--card:#fff;--surface:#f0f0f2;--ink:#252528;--muted:#6b6b72;--border:#e1e1e6;--shadow:none;--radius:12px;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",system-ui,"Noto Sans TC",sans-serif}
:root[data-theme="dark"]{--primary:#e5e5e9;--on-primary:#232326;--accent:#343438;--bg:#1d1d1f;--card:#252527;--surface:#2e2e31;--ink:#f0f0f3;--muted:#aaaab1;--border:#3a3a40;--shadow:none}
@media(prefers-color-scheme:dark){:root:not([data-theme="light"]){--primary:#e5e5e9;--on-primary:#232326;--accent:#343438;--bg:#1d1d1f;--card:#252527;--surface:#2e2e31;--ink:#f0f0f3;--muted:#aaaab1;--border:#3a3a40;--shadow:none}}
:root[data-accent="violet"]{--primary:#70529e;--on-primary:#fff;--accent:#f0eaf8}:root[data-accent="indigo"]{--primary:#4e5d99;--on-primary:#fff;--accent:#ebedf9}
:root[data-accent="violet"][data-theme="dark"]{--primary:#ceb9ee;--on-primary:#281e3a;--accent:#3a304c}:root[data-accent="indigo"][data-theme="dark"]{--primary:#c0cafa;--on-primary:#202942;--accent:#303a55}
@media(prefers-color-scheme:dark){:root[data-accent="violet"]:not([data-theme="light"]){--primary:#ceb9ee;--on-primary:#281e3a;--accent:#3a304c}:root[data-accent="indigo"]:not([data-theme="light"]){--primary:#c0cafa;--on-primary:#202942;--accent:#303a55}}
dialog::backdrop{background:#101014b8;backdrop-filter:blur(3px)}
button{border-radius:9px;font-weight:600;transition:background-color .14s ease,border-color .14s ease,color .14s ease}input,select,textarea{border-radius:8px}.mark{background:transparent;color:var(--ink);border:1px solid var(--border);border-radius:9px}.brand strong{letter-spacing:-.03em}.heading h1{font-weight:650}.workspace-tabs>button{border-radius:8px}.workspace-tabs>button[aria-selected="true"]{color:var(--ink);background:var(--accent)}.identity-avatar{background:var(--surface);color:var(--muted);border-radius:9px}.item{border-radius:10px}.card{box-shadow:none}.model-choice.highlighted{background:var(--accent)}.metric-chip{background:transparent}
.composer{border:1px solid var(--border);border-radius:12px;padding:8px 10px 4px;background:var(--card)}.composer textarea{min-height:38px!important;max-height:200px;padding:5px 4px;line-height:1.5;border:0;background:transparent;resize:none}.composer-tools{margin:0!important}.composer-hint{font-size:.68rem;padding-top:5px}.attachment-buttons .file-button{border:0;background:transparent}.chat-card{border-color:transparent;box-shadow:none}.suggestions{gap:8px}.suggestions button{border-radius:8px}
.desktop-sidebar{display:none}.sidebar-caption{font-size:.7rem;color:var(--muted)}.sidebar-search{margin:8px 0 12px}.sidebar-search input{background:var(--surface);font-size:.78rem;padding:8px 10px}.sidebar-conversations{display:grid;gap:3px;overflow:auto;min-height:0;scrollbar-width:thin}.sidebar-conversation{display:grid;gap:3px;width:100%;text-align:left;justify-content:stretch;background:transparent;color:var(--ink);padding:9px 10px;border-radius:8px;min-width:0}.sidebar-conversation>span{font-size:.8rem;font-weight:500;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.sidebar-conversation>small{font-size:.68rem;color:var(--muted);font-weight:400;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.sidebar-conversation[aria-current="true"]{background:var(--accent)}.sidebar-tools{display:flex;align-items:center;justify-content:space-between;gap:4px}.sidebar-tools button{padding:8px;min-width:48px}.sidebar-footer{font-size:.72rem;color:var(--muted);margin-top:auto;padding:14px 6px 0}.sidebar-more{font-size:.75rem;padding:8px 10px;justify-content:flex-start;background:transparent;color:var(--muted)}
.provider-account-card{border:1px solid var(--border);border-radius:12px;padding:18px;background:var(--card);margin-bottom:14px}.provider-account-heading{display:flex;align-items:center;gap:12px;min-width:0}.provider-account-heading h3{margin:0;overflow-wrap:anywhere;font-size:.95rem}.account-count{margin-left:auto;color:var(--muted);font-size:.76rem}.provider-account-card>.cards{gap:10px}.provider-account-card .item{border:0;border-top:1px solid var(--border);padding:12px 0;background:transparent}.provider-account-card .item{display:grid;grid-template-columns:minmax(0,1fr) auto;column-gap:16px}.provider-account-card .item>strong,.provider-account-card .item>small,.provider-account-card .item>.detail-key-meta{grid-column:1}.provider-account-card .item>button{grid-column:2;grid-row:1/3;align-self:start}.provider-account-card .detail-key-meta{margin-bottom:0}.provider-account-actions{margin:8px 0 0}.provider-account-actions button{font-size:.75rem}.provider-account-card .section-description{font-size:.72rem;margin:8px 0 0}
.site-metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,145px),1fr));gap:16px;margin:18px 0}.site-metric{min-width:0}.site-metric small{display:block;color:var(--muted);font-size:.75rem;margin-bottom:6px}.site-metric strong{font-size:1.1rem;font-weight:600;overflow-wrap:anywhere}.site-notice{white-space:pre-wrap;overflow-wrap:anywhere}.plot-card{border:1px solid var(--border);border-radius:12px;padding:18px;margin:14px 0;background:var(--card);min-width:0}.plot-card h4{margin:0 0 12px}.metric-plot{width:100%;height:180px;display:block;overflow:visible;touch-action:pan-y}.metric-plot text{fill:var(--muted);font-size:10px}.metric-plot .plot-line{stroke:var(--muted);fill:none;stroke-width:1.8;vector-effect:non-scaling-stroke}.metric-plot .plot-dot{fill:var(--card);stroke:var(--ink);stroke-width:2;vector-effect:non-scaling-stroke}.metric-plot .plot-grid{stroke:var(--border);stroke-width:1;stroke-dasharray:3 5;vector-effect:non-scaling-stroke}.plot-dates{display:flex;justify-content:space-between;gap:12px;color:var(--muted);font-size:.7rem}.plot-selected{display:grid;gap:5px;margin:12px 0;overflow-wrap:anywhere}.plot-selected small{color:var(--muted);font-size:.75rem}.plot-actions{display:flex;gap:6px;flex-wrap:wrap}.plot-actions button{font-size:.75rem;padding:8px 10px}.observation-list{display:grid;gap:8px}.observation-row{padding:12px 14px;border:1px solid var(--border);border-radius:9px}.observation-row summary{min-height:40px;padding:4px 0}.observation-row small{display:block;color:var(--muted)}.observation-row pre{max-height:400px;overflow:auto}.observation-tools{display:flex;align-items:end;gap:12px;flex-wrap:wrap}.observation-tools label{flex:1;min-width:130px}
@media(min-width:960px){
 .shell{max-width:none;min-height:100dvh;padding:0 36px 28px 252px}.shell:has(#playground:not([hidden])){padding-bottom:16px}
 header{position:fixed;left:0;top:0;width:216px;height:100dvh;display:flex;align-content:flex-start;align-items:flex-start;padding:24px 16px;background:var(--surface);border:0;border-right:1px solid var(--border);z-index:4;pointer-events:none}.brand{flex:1;gap:9px}.brand strong{font-size:1rem}.brand small{display:none}.brand .mark{width:30px;height:30px;font-size:19px}.header-settings{position:fixed;right:28px;top:16px;pointer-events:auto;font-size:.78rem;background:var(--bg)!important}
 .bottom-nav{position:fixed;top:82px;left:12px;bottom:auto;transform:none;width:192px;padding:0;display:grid;gap:4px;background:transparent;border:0}.bottom-nav button{max-width:none;width:100%;justify-content:flex-start;font-size:.83rem;padding:10px 12px;border-radius:8px}.bottom-nav button.active{color:var(--ink)}
 .desktop-sidebar{display:flex;flex-direction:column;position:fixed;top:260px;bottom:22px;left:12px;width:192px;z-index:5;min-height:0}.desktop-sidebar .sidebar-search input{min-height:40px}.pane{padding-top:76px}.heading{margin:0 0 24px}.heading h1{font-size:1.65rem}.workspace-tabs{margin-bottom:22px}.provider-grid,#my-models{grid-template-columns:1fr}.provider-grid .identity-item{min-height:88px}.identity-avatar{width:36px;height:36px}.identity-item{padding:16px 18px}.chat-card{max-width:1040px;padding:8px 12px 10px;margin-bottom:0}.chat-card:has(#chat-ui:not([hidden])){height:calc(100dvh - 164px);min-height:28rem}#playground>.workspace-tabs{margin-top:0}.target-bar>.model-picker-trigger{max-width:560px}.composer-hint{text-align:right}
 .settings-workspace{display:grid;grid-template-columns:180px minmax(0,1fr);gap:0 24px;align-items:start}.settings-workspace>.workspace-tabs{display:grid;grid-column:1;border:0;gap:4px}.settings-workspace>.workspace-tabs>button{justify-content:flex-start}.settings-workspace>.workspace-panel{grid-column:2;grid-row:1;min-width:0;width:100%;margin-inline:0;max-width:880px}.settings-workspace .card{max-width:900px}.settings-workspace>#settings-general,.settings-workspace>#settings-services,.settings-workspace>#settings-data{margin-inline:0;width:100%}
}
@media(max-width:690px){.provider-account-card{padding:14px}.plot-card{padding:14px}.metric-plot{height:150px}}
:root[data-reduce-motion="true"] *,:root[data-reduce-motion="true"] *::before,:root[data-reduce-motion="true"] *::after{transition:none!important;animation:none!important;scroll-behavior:auto!important}
`
